#!/usr/bin/env python3
"""Verify baseline-free coverage and integrity for production native test shards."""

from __future__ import annotations

import argparse
import collections
import json
import re
import sys
from pathlib import Path
from typing import Any, Iterable

import plan_shards
import targets


PACKAGE_SCHEMA = "entire-graph.windows-ci.package-inventory.v1"
PREPARE_SCHEMA = "entire-graph.windows-ci.prepare-metadata.v1"
SHARD_RUN_SCHEMA = "entire-graph.windows-ci.shard-run.v1"
OTHER_RUN_SCHEMA = "entire-graph.windows-ci.other-run.v1"
REPORT_SCHEMA = "entire-graph.windows-ci.verification.v1"
TERMINAL_ACTIONS = frozenset({"pass", "fail", "skip"})
TARGET_ENVIRONMENT = targets.DEFAULT.environment


def read_json(path: Path) -> Any:
    try:
        with path.open(encoding="utf-8-sig") as handle:
            return json.load(handle)
    except (OSError, json.JSONDecodeError) as error:
        raise ValueError(f"cannot read JSON {path}: {error}") from error


def read_jsonl(path: Path) -> list[dict[str, Any]]:
    events: list[dict[str, Any]] = []
    try:
        handle = path.open(encoding="utf-8-sig")
    except OSError as error:
        raise ValueError(f"cannot read JSONL {path}: {error}") from error
    with handle:
        for line_number, line in enumerate(handle, 1):
            if not line.strip():
                continue
            try:
                value = json.loads(line)
            except json.JSONDecodeError as error:
                raise ValueError(f"{path}:{line_number}: invalid JSON: {error}") from error
            if not isinstance(value, dict):
                raise ValueError(f"{path}:{line_number}: event is not an object")
            events.append(value)
    if not events:
        raise ValueError(f"{path}: event stream is empty")
    return events


def write_json(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".tmp")
    with temporary.open("w", encoding="utf-8", newline="\n") as handle:
        json.dump(value, handle, indent=2, ensure_ascii=False)
        handle.write("\n")
    temporary.replace(path)


def verify_required_zero_exit(
    payload: Any,
    key: str,
    label: str,
    location: str,
    failures: list[str],
    exit_report: list[dict[str, Any]],
) -> None:
    present = isinstance(payload, dict) and key in payload
    value = payload.get(key) if present else None
    passed = present and isinstance(value, int) and not isinstance(value, bool) and value == 0
    exit_report.append(
        {
            "input": label,
            "location": location,
            "present": present,
            "value": value,
            "passed": passed,
        }
    )
    if not present:
        failures.append(f"{label} is missing required exit field {location}")
    elif not passed:
        failures.append(f"{label} has nonzero or non-integer exit at {location}: {value!r}")


def verify_prepare_operation_exits(
    prepare: dict[str, Any],
    heavy_packages: set[str],
    label: str,
    failures: list[str],
    exit_report: list[dict[str, Any]],
) -> None:
    verify_required_zero_exit(prepare, "exitCode", label, "$.exitCode", failures, exit_report)
    operations = prepare.get("operations")
    if not isinstance(operations, list):
        failures.append(f"{label} operations are not a list")
        return
    actual: collections.Counter[tuple[Any, Any]] = collections.Counter()
    for index, operation in enumerate(operations):
        if not isinstance(operation, dict):
            failures.append(f"{label} operation {index} is not an object")
            continue
        phase = operation.get("phase")
        package = operation.get("package")
        actual[(phase, package)] += 1
        verify_required_zero_exit(
            operation,
            "exitCode",
            label,
            f"$.operations[{index}].exitCode",
            failures,
            exit_report,
        )
    expected: collections.Counter[tuple[Any, Any]] = collections.Counter(
        {
            ("worktree-clean-before", None): 1,
            ("repository-sha", None): 1,
            ("repository-sha-after", None): 1,
            ("go-version", None): 1,
            ("go-environment", None): 1,
            ("go-list-all", None): 1,
            ("worktree-clean-after", None): 1,
        }
    )
    for package in heavy_packages:
        for phase in ("go-list-package", "testmain-inventory", "compile", "list"):
            expected[(phase, package)] += 1
    if actual != expected:
        failures.append("prepare operation phase/package set differs from the required schema")


def validate_plan(
    plan: dict[str, Any],
    inventories: list[dict[str, Any]],
    failures: list[str],
    target: targets.Target = targets.DEFAULT,
) -> tuple[
    dict[tuple[str, str], int],
    dict[tuple[int, str], dict[str, Any]],
    dict[str, dict[str, str]],
]:
    inventory_by_package = {item["importPath"]: item for item in inventories}
    root_details = {
        package: {root["name"]: root["kind"] for root in inventory["roots"]}
        for package, inventory in inventory_by_package.items()
    }
    if plan.get("schema") != plan_shards.PLAN_SCHEMA:
        raise ValueError(f"unexpected shard plan schema {plan.get('schema')!r}")
    if plan.get("targetEnvironment") != target.environment:
        failures.append(f"plan target is not exactly {target.description}")
    settings = plan.get("settings")
    if not isinstance(settings, dict) or settings.get("shuffle") != "off":
        failures.append("plan does not preserve shuffle=off semantics")
    if plan.get("inventorySetSha256") != plan_shards._inventory_digest(inventories):
        failures.append("plan inventory digest does not match compiled inventories")
    plan_packages = plan.get("packages")
    if not isinstance(plan_packages, list):
        failures.append("plan packages are not a list")
        plan_packages = []
    normalized_plan_packages: dict[str, dict[str, Any]] = {}
    for item in plan_packages:
        if not isinstance(item, dict) or not isinstance(item.get("importPath"), str):
            failures.append("plan contains a malformed package entry")
            continue
        package = item["importPath"]
        if package in normalized_plan_packages:
            failures.append(f"plan declares package {package} more than once")
        normalized_plan_packages[package] = item
    if set(normalized_plan_packages) != set(inventory_by_package):
        failures.append("plan package set differs from compiled inventories")
    for package in sorted(set(normalized_plan_packages) & set(inventory_by_package)):
        planned, inventory = normalized_plan_packages[package], inventory_by_package[package]
        for key in (
            "packageDirectoryRelative",
            "binaryName",
            "binarySha256",
            "binarySizeBytes",
            "testMainDeclarations",
        ):
            if planned.get(key) != inventory.get(key):
                failures.append(f"plan {package} {key} differs from compiled inventory")
        if planned.get("rootCount") != len(inventory["roots"]):
            failures.append(f"plan {package} root count differs from compiled inventory")

    shards = plan.get("shards")
    shard_count = plan.get("shardCount")
    if (
        not isinstance(shard_count, int)
        or isinstance(shard_count, bool)
        or not isinstance(shards, list)
        or len(shards) != shard_count
    ):
        failures.append("plan shardCount does not match the shard array")
        shards = []
    assignment_for_root: dict[tuple[str, str], int] = {}
    process_assignments: dict[tuple[int, str], dict[str, Any]] = {}
    duplicate_roots: list[str] = []
    regex_mismatches: list[str] = []
    for position, shard in enumerate(shards):
        if not isinstance(shard, dict) or shard.get("index") != position:
            failures.append(f"plan shard at position {position} has a mismatched index")
            continue
        assignments = shard.get("assignments")
        if not isinstance(assignments, list) or not assignments:
            failures.append(f"plan shard {position} has no assignments")
            continue
        seen_packages: set[str] = set()
        counted_roots = 0
        for assignment in assignments:
            if not isinstance(assignment, dict):
                failures.append(f"plan shard {position} contains a malformed assignment")
                continue
            package = assignment.get("importPath")
            if not isinstance(package, str) or package not in inventory_by_package:
                failures.append(f"plan shard {position} references unknown package {package!r}")
                continue
            if package in seen_packages:
                failures.append(f"plan shard {position} assigns package {package} more than once")
            seen_packages.add(package)
            process_assignments[(position, package)] = assignment
            inventory = inventory_by_package[package]
            for key in ("packageDirectoryRelative", "binaryName", "binarySha256"):
                if assignment.get(key) != inventory.get(key):
                    failures.append(f"plan shard {position} {package} {key} differs from inventory")
            roots = assignment.get("roots")
            expression = assignment.get("runRegex")
            if not isinstance(roots, list) or not roots or not isinstance(expression, str):
                failures.append(f"plan shard {position} {package} has malformed roots or regex")
                continue
            names: list[str] = []
            for root in roots:
                name = root.get("name") if isinstance(root, dict) else None
                kind = root.get("kind") if isinstance(root, dict) else None
                if (
                    not isinstance(name, str)
                    or name not in root_details[package]
                    or kind != root_details[package].get(name)
                ):
                    failures.append(f"plan shard {position} {package} contains an unknown root")
                    continue
                key = (package, name)
                if key in assignment_for_root:
                    duplicate_roots.append(f"{package}::{name}")
                assignment_for_root[key] = position
                names.append(name)
            counted_roots += len(names)
            if len(names) != len(set(names)):
                failures.append(f"plan shard {position} {package} repeats a root")
            try:
                compiled = re.compile(expression)
            except re.error as error:
                failures.append(f"plan shard {position} {package} has invalid regex: {error}")
                continue
            selected = {name for name in root_details[package] if compiled.fullmatch(name)}
            if selected != set(names):
                regex_mismatches.append(f"shard {position} {package}")
        if shard.get("rootCount") != counted_roots:
            failures.append(f"plan shard {position} rootCount differs from assignments")
    expected_roots = {
        (package, name) for package, names in root_details.items() for name in names
    }
    missing_roots = expected_roots - set(assignment_for_root)
    unexpected_roots = set(assignment_for_root) - expected_roots
    if missing_roots:
        failures.append(f"plan omits {len(missing_roots)} compiled runnable roots")
    if unexpected_roots:
        failures.append(f"plan adds {len(unexpected_roots)} unknown runnable roots")
    if duplicate_roots:
        failures.append(f"plan assigns {len(duplicate_roots)} runnable roots more than once")
    if regex_mismatches:
        failures.append(f"{len(regex_mismatches)} plan regexes select a different root set")
    if plan.get("rootCount") != len(expected_roots):
        failures.append("plan rootCount differs from compiled inventories")
    return assignment_for_root, process_assignments, root_details


def verify_shards(
    root: Path,
    plan: dict[str, Any],
    plan_sha256: str,
    inventories: list[dict[str, Any]],
    assignment_for_root: dict[tuple[str, str], int],
    process_assignments: dict[tuple[int, str], dict[str, Any]],
    root_details: dict[str, dict[str, str]],
    failures: list[str],
    exit_report: list[dict[str, Any]],
    target: targets.Target = targets.DEFAULT,
) -> dict[str, Any]:
    metadata_paths = sorted(root.rglob("shard-metadata.json"))
    shard_count = plan.get("shardCount")
    if len(metadata_paths) != shard_count:
        failures.append(f"found {len(metadata_paths)} shard metadata files, want {shard_count}")
    by_index: dict[int, tuple[dict[str, Any], Path]] = {}
    top_runs: collections.Counter[tuple[str, str]] = collections.Counter()
    top_terminals: collections.Counter[tuple[str, str, str]] = collections.Counter()
    package_starts: collections.Counter[tuple[int, str]] = collections.Counter()
    package_terminals: collections.Counter[tuple[int, str, str]] = collections.Counter()
    unexpected_event_roots: set[str] = set()
    event_count = 0
    for metadata_path in metadata_paths:
        metadata = read_json(metadata_path)
        if not isinstance(metadata, dict) or metadata.get("schema") != SHARD_RUN_SCHEMA:
            failures.append(f"{metadata_path}: unexpected shard metadata schema")
            continue
        verify_required_zero_exit(
            metadata,
            "exitCode",
            str(metadata_path),
            "$.exitCode",
            failures,
            exit_report,
        )
        verify_required_zero_exit(
            metadata,
            "cleanTestCacheExitCode",
            str(metadata_path),
            "$.cleanTestCacheExitCode",
            failures,
            exit_report,
        )
        index = metadata.get("shardIndex")
        if not isinstance(index, int) or isinstance(index, bool) or not 0 <= index < shard_count:
            failures.append(f"{metadata_path}: invalid shard index {index!r}")
            continue
        if index in by_index:
            failures.append(f"shard {index} has duplicate metadata artifacts")
            continue
        by_index[index] = (metadata, metadata_path)
        if metadata.get("errors") != []:
            failures.append(f"shard {index} metadata contains errors")
        if metadata.get("repositorySha") != plan.get("repositorySha"):
            failures.append(f"shard {index} repository SHA differs from plan")
        if metadata.get("repositoryShaAfter") != plan.get("repositorySha"):
            failures.append(f"shard {index} post-run repository SHA differs from plan")
        if metadata.get("goVersion") != plan.get("goVersion"):
            failures.append(f"shard {index} Go version differs from plan")
        if metadata.get("targetEnvironment") != target.environment:
            failures.append(f"shard {index} target is not exactly {target.description}")
        if metadata.get("targetEnvironment") != plan.get("targetEnvironment"):
            failures.append(f"shard {index} target differs from plan")
        if metadata.get("trackedWorktreeCleanBefore") is not True:
            failures.append(f"shard {index} did not prove a clean tracked worktree before execution")
        if metadata.get("trackedWorktreeCleanAfter") is not True:
            failures.append(f"shard {index} did not prove a clean tracked worktree after execution")
        if not isinstance(metadata.get("goToolDirectory"), str) or not metadata["goToolDirectory"]:
            failures.append(f"shard {index} omitted its resolved Go tool directory")
        if metadata.get("planSha256") != plan_sha256:
            failures.append(f"shard {index} plan hash differs from the downloaded bundle")
        if metadata.get("shardCount") != shard_count:
            failures.append(f"shard {index} metadata has the wrong shard count")
        for key in ("timeout", "shuffle", "testParallel", "goMaxProcs", "commandLineLimit"):
            if metadata.get(key) != plan.get("settings", {}).get(key):
                failures.append(f"shard {index} metadata setting {key} differs from plan")
        expected_assignments = {
            package: assignment
            for (assignment_index, package), assignment in process_assignments.items()
            if assignment_index == index
        }
        invocations = metadata.get("invocations")
        if not isinstance(invocations, list):
            failures.append(f"shard {index} invocations are not a list")
            invocations = []
        actual_invocations: dict[str, dict[str, Any]] = {}
        for invocation_index, invocation in enumerate(invocations):
            verify_required_zero_exit(
                invocation,
                "exitCode",
                str(metadata_path),
                f"$.invocations[{invocation_index}].exitCode",
                failures,
                exit_report,
            )
            package = invocation.get("package") if isinstance(invocation, dict) else None
            if not isinstance(package, str) or package in actual_invocations:
                failures.append(f"shard {index} has a malformed or duplicate invocation")
                continue
            actual_invocations[package] = invocation
            expected = expected_assignments.get(package)
            if expected is None:
                failures.append(f"shard {index} invoked unexpected package {package}")
                continue
            if invocation.get("binaryName") != expected.get("binaryName"):
                failures.append(f"shard {index} {package} binary name differs from plan")
            if invocation.get("binarySha256") != expected.get("binarySha256"):
                failures.append(f"shard {index} {package} binary hash differs from plan")
            if invocation.get("rootCount") != len(expected.get("roots", [])):
                failures.append(f"shard {index} {package} root count differs from plan")
            if invocation.get("workingDirectoryRelative") != expected.get(
                "packageDirectoryRelative"
            ):
                failures.append(f"shard {index} {package} working directory differs from plan")
            if invocation.get("paniconexit0") is not True:
                failures.append(f"shard {index} {package} omitted -test.paniconexit0")
            if invocation.get("pwdMatchesPackageDirectory") is not True:
                failures.append(f"shard {index} {package} did not set PWD to its package directory")
            if invocation.get("goToolDirectoryPrependedToPath") is not True:
                failures.append(f"shard {index} {package} did not prepend the Go tool directory to PATH")
            command_units = invocation.get(target.command_line_metric)
            if (
                not isinstance(command_units, int)
                or isinstance(command_units, bool)
                or not 1 <= command_units <= plan["settings"]["commandLineLimit"]
            ):
                failures.append(f"shard {index} {package} command line exceeded or omitted its budget")
            if not targets.valid_argument_area(target, invocation):
                failures.append(
                    f"shard {index} {package} exec argument area exceeded or omitted its kernel limit"
                )
        if set(actual_invocations) != set(expected_assignments):
            failures.append(f"shard {index} invocation package set differs from plan")

        events_path = metadata_path.with_name("shard-events.jsonl")
        events = read_jsonl(events_path)
        event_count += len(events)
        expected_packages = set(expected_assignments)
        for event in events:
            action = event.get("Action")
            package = event.get("Package")
            if not isinstance(action, str) or not isinstance(package, str):
                failures.append(f"shard {index} contains an event without Action or Package")
                continue
            if package not in expected_packages:
                failures.append(f"shard {index} emitted an unexpected package {package}")
                continue
            test = event.get("Test")
            if test is None:
                if action == "start":
                    package_starts[(index, package)] += 1
                elif action in TERMINAL_ACTIONS:
                    package_terminals[(index, package, action)] += 1
                    if action != "pass":
                        failures.append(f"shard {index} package {package} terminated with {action}")
                continue
            if not isinstance(test, str) or not test:
                failures.append(f"shard {index} {package} has a malformed test event")
                continue
            root = test.split("/", 1)[0]
            key = (package, root)
            if root not in root_details.get(package, {}):
                unexpected_event_roots.add(f"{package}::{root}")
                continue
            if assignment_for_root.get(key) != index:
                failures.append(f"shard {index} emitted unassigned root {package}::{root}")
            if action == "fail":
                failures.append(f"shard {index} has failed test event {package}::{test}")
            if test == root:
                if action == "run":
                    top_runs[key] += 1
                elif action in TERMINAL_ACTIONS:
                    top_terminals[(package, root, action)] += 1
    if set(by_index) != set(range(shard_count)):
        failures.append("shard result indexes are incomplete")
    if unexpected_event_roots:
        failures.append(f"shards emitted {len(unexpected_event_roots)} roots absent from compiled inventories")

    root_mismatches: list[dict[str, Any]] = []
    for key, assigned_shard in sorted(assignment_for_root.items()):
        package, name = key
        run_count = top_runs[key]
        terminals = {
            action: top_terminals[(package, name, action)] for action in sorted(TERMINAL_ACTIONS)
        }
        if run_count != 1 or sum(terminals.values()) != 1 or terminals["fail"] != 0:
            root_mismatches.append(
                {
                    "root": f"{package}::{name}",
                    "shard": assigned_shard,
                    "runCount": run_count,
                    "terminalCounts": terminals,
                }
            )
    if root_mismatches:
        failures.append(f"{len(root_mismatches)} planned roots lack exactly one run and successful terminal")

    process_mismatches: list[dict[str, Any]] = []
    for index, package in sorted(process_assignments):
        terminals = {
            action: package_terminals[(index, package, action)] for action in sorted(TERMINAL_ACTIONS)
        }
        if package_starts[(index, package)] != 1 or terminals != {"fail": 0, "pass": 1, "skip": 0}:
            process_mismatches.append(
                {
                    "shard": index,
                    "package": package,
                    "startCount": package_starts[(index, package)],
                    "terminalCounts": terminals,
                }
            )
    if process_mismatches:
        failures.append(f"{len(process_mismatches)} shard package processes have wrong start/terminal multiplicity")
    return {
        "metadataCount": len(metadata_paths),
        "eventCount": event_count,
        "expectedRootCount": len(assignment_for_root),
        "topLevelRunCount": sum(top_runs.values()),
        "topLevelTerminalCount": sum(top_terminals.values()),
        "unexpectedRoots": sorted(unexpected_event_roots)[:100],
        "rootMismatches": root_mismatches[:100],
        "processMismatches": process_mismatches[:100],
        "differencesTruncated": len(root_mismatches) > 100 or len(process_mismatches) > 100,
    }


def verify_other(
    root: Path,
    plan: dict[str, Any],
    plan_sha256: str,
    package_inventory: dict[str, Any],
    package_inventory_sha256: str,
    failures: list[str],
    exit_report: list[dict[str, Any]],
    target: targets.Target = targets.DEFAULT,
) -> dict[str, Any]:
    metadata_paths = sorted(root.rglob("other-metadata.json"))
    event_paths = sorted(root.rglob("other-events.jsonl"))
    if len(metadata_paths) != 1 or len(event_paths) != 1:
        raise ValueError(
            f"non-heavy artifact has {len(metadata_paths)} metadata and {len(event_paths)} event files, want one each"
        )
    metadata = read_json(metadata_paths[0])
    if not isinstance(metadata, dict) or metadata.get("schema") != OTHER_RUN_SCHEMA:
        raise ValueError("unexpected non-heavy metadata schema")
    for key in ("exitCode", "cleanTestCacheExitCode", "testExitCode"):
        verify_required_zero_exit(
            metadata,
            key,
            str(metadata_paths[0]),
            f"$.{key}",
            failures,
            exit_report,
        )
    if metadata.get("errors") != []:
        failures.append("non-heavy metadata contains errors")
    if metadata.get("repositorySha") != plan.get("repositorySha"):
        failures.append("non-heavy repository SHA differs from plan")
    if metadata.get("repositoryShaAfter") != plan.get("repositorySha"):
        failures.append("non-heavy post-run repository SHA differs from plan")
    if metadata.get("goVersion") != plan.get("goVersion"):
        failures.append("non-heavy Go version differs from plan")
    if metadata.get("targetEnvironment") != target.environment:
        failures.append(f"non-heavy target is not exactly {target.description}")
    if metadata.get("targetEnvironment") != plan.get("targetEnvironment"):
        failures.append("non-heavy target differs from plan")
    if metadata.get("trackedWorktreeCleanBefore") is not True:
        failures.append("non-heavy run did not prove a clean tracked worktree before execution")
    if metadata.get("trackedWorktreeCleanAfter") is not True:
        failures.append("non-heavy run did not prove a clean tracked worktree after execution")
    if metadata.get("planSha256") != plan_sha256:
        failures.append("non-heavy plan hash differs from the downloaded bundle")
    if metadata.get("packageInventorySha256") != package_inventory_sha256:
        failures.append("non-heavy package-inventory hash differs from the downloaded bundle")
    for key in ("timeout", "shuffle", "testParallel", "goMaxProcs", "commandLineLimit"):
        if metadata.get(key) != plan.get("settings", {}).get(key):
            failures.append(f"non-heavy metadata setting {key} differs from plan")
    command_units = metadata.get(target.command_line_metric)
    if (
        not isinstance(command_units, int)
        or isinstance(command_units, bool)
        or not 1 <= command_units <= plan["settings"]["commandLineLimit"]
    ):
        failures.append("non-heavy command line exceeded or omitted its budget")
    if not targets.valid_argument_area(target, metadata):
        failures.append("non-heavy exec argument area exceeded or omitted its kernel limit")

    expected_packages = sorted(
        row["importPath"] for row in package_inventory["packages"] if not row["heavy"]
    )
    if metadata.get("expectedPackages") != expected_packages:
        failures.append(
            f"non-heavy metadata package list differs from target-{target.host_label} inventory"
        )
    events = read_jsonl(event_paths[0])
    starts: collections.Counter[str] = collections.Counter()
    terminals: collections.Counter[tuple[str, str]] = collections.Counter()
    unexpected_packages: set[str] = set()
    benchmark_roots: set[str] = set()
    failed_tests: set[str] = set()
    build_output_count = 0
    for event in events:
        action, package = event.get("Action"), event.get("Package")
        if not isinstance(action, str):
            failures.append("non-heavy stream contains an event without Action or Package")
            continue
        if not isinstance(package, str):
            if (
                action == "build-output"
                and isinstance(event.get("ImportPath"), str)
                and event["ImportPath"]
                and isinstance(event.get("Output"), str)
            ):
                build_output_count += 1
                continue
            failures.append("non-heavy stream contains an event without Action or Package")
            continue
        if package not in expected_packages:
            unexpected_packages.add(package)
            continue
        test = event.get("Test")
        if test is None:
            if action == "start":
                starts[package] += 1
            elif action in TERMINAL_ACTIONS:
                terminals[(package, action)] += 1
                if action == "fail":
                    failures.append(f"non-heavy package {package} failed")
        elif isinstance(test, str):
            root = test.split("/", 1)[0]
            if root.startswith("Benchmark") and action in {"run", *TERMINAL_ACTIONS}:
                benchmark_roots.add(f"{package}::{root}")
            if action == "fail":
                failed_tests.add(f"{package}::{test}")
        else:
            failures.append("non-heavy stream contains a malformed Test field")
    if unexpected_packages:
        failures.append(f"non-heavy stream emitted {len(unexpected_packages)} unexpected packages")
    if benchmark_roots:
        failures.append(f"non-heavy default invocation ran {len(benchmark_roots)} benchmarks")
    if failed_tests:
        failures.append(f"non-heavy stream contains {len(failed_tests)} failed test events")
    package_mismatches: list[dict[str, Any]] = []
    for package in expected_packages:
        counts = {action: terminals[(package, action)] for action in sorted(TERMINAL_ACTIONS)}
        if starts[package] != 1 or sum(counts.values()) != 1 or counts["fail"] != 0:
            package_mismatches.append(
                {"package": package, "startCount": starts[package], "terminalCounts": counts}
            )
    if package_mismatches:
        failures.append(f"{len(package_mismatches)} non-heavy packages lack exactly one start and successful terminal")
    return {
        "eventCount": len(events),
        "buildOutputCount": build_output_count,
        "expectedPackageCount": len(expected_packages),
        "unexpectedPackages": sorted(unexpected_packages),
        "benchmarkRoots": sorted(benchmark_roots),
        "failedTests": sorted(failed_tests)[:100],
        "packageMismatches": package_mismatches[:100],
        "differencesTruncated": len(failed_tests) > 100 or len(package_mismatches) > 100,
    }


def verify(args: argparse.Namespace) -> dict[str, Any]:
    failures: list[str] = []
    exit_report: list[dict[str, Any]] = []
    report: dict[str, Any] = {
        "schema": REPORT_SCHEMA,
        "passed": False,
        "failures": failures,
    }
    target = targets.resolve(getattr(args, "target", targets.DEFAULT.name))
    bundle = args.bundle.resolve(strict=True)
    plan_path = bundle / "plan.json"
    package_path = bundle / "package-inventory.json"
    prepare_path = bundle / "prepare-metadata.json"
    settings_path = bundle / "settings.json"
    weights_path = bundle / "historical-weights.json"
    inventory_paths = sorted((bundle / "inventories").glob("*.inventory.json"))
    if not inventory_paths:
        raise ValueError("bundle contains no compiled inventories")
    inventories = plan_shards.load_inventories(inventory_paths, target)
    plan = read_json(plan_path)
    if not isinstance(plan, dict):
        raise ValueError("plan is not an object")
    settings = plan_shards.load_settings(settings_path)
    if plan_shards.settings_target(settings) is not target:
        failures.append(f"bundled settings target is not exactly {target.description}")
    if plan.get("shardCount") != settings.get("shardCount"):
        failures.append("bundled settings shard count differs from plan")
    for key in (
        "timeout",
        "commandLineLimit",
        "shuffle",
        "testParallel",
        "goMaxProcs",
        "defaultWeightSeconds",
    ):
        if plan.get("settings", {}).get(key) != settings.get(key):
            failures.append(f"bundled setting {key} differs from plan")
    if plan.get("historicalWeights", {}).get("sha256") != plan_shards.sha256_file(weights_path):
        failures.append("bundled historical-weight hash differs from plan")

    prepare = read_json(prepare_path)
    if not isinstance(prepare, dict) or prepare.get("schema") != PREPARE_SCHEMA:
        failures.append("unexpected prepare metadata schema")
    else:
        verify_prepare_operation_exits(
            prepare,
            {inventory["importPath"] for inventory in inventories},
            str(prepare_path),
            failures,
            exit_report,
        )
        if prepare.get("repositorySha") != plan.get("repositorySha"):
            failures.append("prepare repository SHA differs from plan")
        if prepare.get("repositoryShaAfter") != plan.get("repositorySha"):
            failures.append("prepare post-run repository SHA differs from plan")
        if prepare.get("goVersion") != plan.get("goVersion"):
            failures.append("prepare Go version differs from plan")
        if prepare.get("targetEnvironment") != target.environment:
            failures.append(f"prepare target is not exactly {target.description}")
        if prepare.get("targetEnvironment") != plan.get("targetEnvironment"):
            failures.append("prepare target differs from plan")
        if prepare.get("trackedWorktreeCleanBefore") is not True:
            failures.append("prepare did not prove a clean tracked worktree before execution")
        if prepare.get("trackedWorktreeCleanAfter") is not True:
            failures.append("prepare did not prove a clean tracked worktree after execution")
        if not isinstance(prepare.get("goToolDirectory"), str) or not prepare["goToolDirectory"]:
            failures.append("prepare omitted its resolved Go tool directory")

    for inventory in inventories:
        binary = bundle / "binaries" / inventory["binaryName"]
        if not binary.is_file():
            failures.append(f"compiled binary is missing: {inventory['binaryName']}")
            continue
        if binary.stat().st_size != inventory["binarySizeBytes"]:
            failures.append(f"compiled binary size differs from inventory: {inventory['binaryName']}")
        if plan_shards.sha256_file(binary) != inventory["binarySha256"]:
            failures.append(f"compiled binary hash differs from inventory: {inventory['binaryName']}")

    assignment_for_root, process_assignments, root_details = validate_plan(
        plan, inventories, failures, target
    )
    package_inventory = read_json(package_path)
    if not isinstance(package_inventory, dict) or package_inventory.get("schema") != PACKAGE_SCHEMA:
        raise ValueError(f"unexpected target-{target.host_label} package inventory schema")
    if package_inventory.get("repositorySha") != plan.get("repositorySha"):
        failures.append("package inventory repository SHA differs from plan")
    if package_inventory.get("goVersion") != plan.get("goVersion"):
        failures.append("package inventory Go version differs from plan")
    package_target = {
        "GOOS": package_inventory.get("goos"),
        "GOARCH": package_inventory.get("goarch"),
        "CGO_ENABLED": package_inventory.get("cgoEnabled"),
    }
    if package_target != target.environment:
        failures.append(f"package inventory target is not exactly {target.description}")
    if package_target != plan.get("targetEnvironment"):
        failures.append("package inventory target differs from plan")
    package_rows = package_inventory.get("packages")
    if not isinstance(package_rows, list) or not package_rows:
        raise ValueError(f"target-{target.host_label} package inventory is empty")
    package_names: set[str] = set()
    heavy_names: set[str] = set()
    for row in package_rows:
        if not isinstance(row, dict) or not isinstance(row.get("heavy"), bool):
            raise ValueError(
                f"target-{target.host_label} package inventory contains a malformed row"
            )
        package = row.get("importPath")
        if not isinstance(package, str) or not package or package in package_names:
            raise ValueError(
                f"target-{target.host_label} package inventory contains a missing or duplicate package"
            )
        package_names.add(package)
        if row["heavy"]:
            heavy_names.add(package)
    if heavy_names != set(root_details):
        failures.append(
            f"target-{target.host_label} heavy package declarations differ from compiled inventories"
        )
    configured_test_mains = {
        item["importPath"]: item["expectedTestMainDeclarations"]
        for item in settings["heavyPackages"]
    }
    inventory_test_mains = {
        item["importPath"]: item["testMainDeclarations"] for item in inventories
    }
    if configured_test_mains != inventory_test_mains:
        failures.append("compiled TestMain declarations differ from bundled settings")

    report["shards"] = verify_shards(
        args.shard_results.resolve(strict=True),
        plan,
        plan_shards.sha256_file(plan_path),
        inventories,
        assignment_for_root,
        process_assignments,
        root_details,
        failures,
        exit_report,
        target,
    )
    report["otherPackages"] = verify_other(
        args.other_results.resolve(strict=True),
        plan,
        plan_shards.sha256_file(plan_path),
        package_inventory,
        plan_shards.sha256_file(package_path),
        failures,
        exit_report,
        target,
    )
    report["inventory"] = {
        "repositorySha": plan.get("repositorySha"),
        "goVersion": plan.get("goVersion"),
        "targetEnvironment": plan.get("targetEnvironment"),
        "packageCount": len(package_names),
        "heavyPackageCount": len(heavy_names),
        "runnableRootCount": len(assignment_for_root),
        "excludedBenchmarkCount": sum(len(item["excludedBenchmarks"]) for item in inventories),
        "historicallyWeightedCount": plan.get("historicalWeights", {}).get("usedCount"),
        "defaultWeightedCount": plan.get("historicalWeights", {}).get("defaultedCount"),
    }
    report["exitCodes"] = exit_report
    report["passed"] = not failures
    return report


def parse_args(argv: list[str]) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--bundle", type=Path, required=True)
    parser.add_argument("--shard-results", type=Path, required=True)
    parser.add_argument("--other-results", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--target", default=targets.DEFAULT.name, choices=sorted(targets.TARGETS))
    return parser.parse_args(argv)


def main(argv: list[str] | None = None) -> int:
    args = parse_args(sys.argv[1:] if argv is None else argv)
    try:
        report = verify(args)
    except (ValueError, OSError, KeyError, TypeError) as error:
        report = {"schema": REPORT_SCHEMA, "passed": False, "failures": [str(error)]}
    try:
        write_json(args.output, report)
    except OSError as error:
        print(f"error: cannot write report {args.output}: {error}", file=sys.stderr)
        return 2
    if not report.get("passed"):
        for failure in report.get("failures", []):
            print(f"FAIL: {failure}", file=sys.stderr)
        return 1
    print(
        f"{targets.resolve(args.target).host_label} shard coverage and integrity verification passed"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Build a deterministic, fail-closed plan from compiled native test binaries."""

from __future__ import annotations

import argparse
import hashlib
import json
import math
import re
import sys
from collections import defaultdict
from pathlib import Path, PurePosixPath
from typing import Any, Iterable

import targets


# The schema identifiers keep their historical `windows-ci` prefix for every
# target; the target itself is carried by `targetEnvironment`.
SETTINGS_SCHEMA = "entire-graph.windows-ci.settings.v1"
WEIGHTS_SCHEMA = "entire-graph.windows-ci.historical-weights.v1"
INVENTORY_SCHEMA = "entire-graph.windows-ci.compiled-inventory.v1"
PLAN_SCHEMA = "entire-graph.windows-ci.shard-plan.v1"
ROOT_KINDS = ("Test", "Example", "Fuzz")
_TIMEOUT = re.compile(r"^[1-9][0-9]*(?:ns|us|µs|ms|s|m|h)$")
_SHA = re.compile(r"^[0-9a-f]{40}$")
_SHA256 = re.compile(r"^[0-9a-f]{64}$")
# The default target's identity, kept as a module constant for existing callers.
TARGET_ENVIRONMENT = targets.DEFAULT.environment


def settings_target(settings: dict[str, Any]) -> targets.Target:
    """The target a settings object names; a missing key is the Windows default."""
    return targets.resolve(settings.get("target", targets.DEFAULT.name))


def read_json(path: Path) -> Any:
    try:
        with path.open(encoding="utf-8-sig") as handle:
            return json.load(handle)
    except (OSError, json.JSONDecodeError) as error:
        raise ValueError(f"cannot read JSON {path}: {error}") from error


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    try:
        with path.open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(chunk)
    except OSError as error:
        raise ValueError(f"cannot hash {path}: {error}") from error
    return digest.hexdigest()


def write_json(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".tmp")
    with temporary.open("w", encoding="utf-8", newline="\n") as handle:
        json.dump(value, handle, indent=2, ensure_ascii=False)
        handle.write("\n")
    temporary.replace(path)


def _safe_relative_directory(value: Any, label: str) -> str:
    if not isinstance(value, str) or not value or "\\" in value:
        raise ValueError(f"{label} must be a non-empty normalized POSIX path")
    path = PurePosixPath(value)
    if path.is_absolute() or ".." in path.parts or "." in path.parts:
        raise ValueError(f"{label} is unsafe: {value!r}")
    return value


def load_settings(path: Path) -> dict[str, Any]:
    value = read_json(path)
    if not isinstance(value, dict) or value.get("schema") != SETTINGS_SCHEMA:
        raise ValueError(f"{path}: unexpected settings schema")
    target = settings_target(value)
    shard_count = value.get("shardCount")
    default_weight = value.get("defaultWeightSeconds")
    command_limit = value.get("commandLineLimit")
    timeout = value.get("timeout")
    if not isinstance(shard_count, int) or isinstance(shard_count, bool) or not 1 <= shard_count <= 64:
        raise ValueError(f"{path}: shardCount must be an integer from 1 through 64")
    if (
        not isinstance(default_weight, (int, float))
        or isinstance(default_weight, bool)
        or not math.isfinite(float(default_weight))
        or float(default_weight) <= 0
    ):
        raise ValueError(f"{path}: defaultWeightSeconds must be finite and positive")
    if not target.valid_command_line_limit(command_limit):
        raise ValueError(
            f"{path}: commandLineLimit must be from 1024 through {target.command_line_limit_maximum}"
        )
    if not isinstance(timeout, str) or not _TIMEOUT.fullmatch(timeout):
        raise ValueError(f"{path}: timeout is not a positive Go duration")
    if value.get("shuffle") != "off":
        raise ValueError(f"{path}: production sharding currently requires shuffle='off'")
    for name in ("testParallel", "goMaxProcs"):
        setting = value.get(name)
        if setting is not None and (
            not isinstance(setting, int) or isinstance(setting, bool) or not 1 <= setting <= 1024
        ):
            raise ValueError(f"{path}: {name} must be null or an integer from 1 through 1024")

    heavy = value.get("heavyPackages")
    if not isinstance(heavy, list) or not heavy:
        raise ValueError(f"{path}: heavyPackages must be a non-empty list")
    seen_arguments: set[str] = set()
    seen_imports: set[str] = set()
    seen_binaries: set[str] = set()
    normalized: list[dict[str, Any]] = []
    for position, item in enumerate(heavy):
        if not isinstance(item, dict):
            raise ValueError(f"{path}: heavyPackages[{position}] is not an object")
        argument = item.get("argument")
        import_path = item.get("importPath")
        binary_name = item.get("binaryName")
        expected_test_mains = item.get("expectedTestMainDeclarations")
        if not isinstance(argument, str) or not argument.startswith("./") or " " in argument:
            raise ValueError(f"{path}: unsafe heavy package argument {argument!r}")
        if not isinstance(import_path, str) or not import_path or any(c.isspace() for c in import_path):
            raise ValueError(f"{path}: unsafe heavy package importPath {import_path!r}")
        if (
            not isinstance(binary_name, str)
            or Path(binary_name).name != binary_name
            or "/" in binary_name
            or "\\" in binary_name
            or not binary_name.endswith(target.binary_suffix)
        ):
            raise ValueError(f"{path}: unsafe heavy package binaryName {binary_name!r}")
        if argument in seen_arguments or import_path in seen_imports or binary_name in seen_binaries:
            raise ValueError(f"{path}: duplicate heavy package field at index {position}")
        if not isinstance(expected_test_mains, list):
            raise ValueError(
                f"{path}: heavyPackages[{position}].expectedTestMainDeclarations must be a list"
            )
        normalized_test_mains: list[dict[str, str]] = []
        seen_test_main_files: set[str] = set()
        for declaration_position, declaration in enumerate(expected_test_mains):
            if not isinstance(declaration, dict):
                raise ValueError(
                    f"{path}: heavyPackages[{position}].expectedTestMainDeclarations[{declaration_position}] is not an object"
                )
            file_name = declaration.get("file")
            source_hash = declaration.get("normalizedSourceSha256")
            if (
                not isinstance(file_name, str)
                or not file_name
                or Path(file_name).name != file_name
                or "/" in file_name
                or "\\" in file_name
                or file_name in seen_test_main_files
            ):
                raise ValueError(
                    f"{path}: invalid or duplicate expected TestMain file {file_name!r}"
                )
            if not isinstance(source_hash, str) or not _SHA256.fullmatch(source_hash):
                raise ValueError(
                    f"{path}: invalid expected TestMain normalized source hash for {file_name!r}"
                )
            seen_test_main_files.add(file_name)
            normalized_test_mains.append(
                {"file": file_name, "normalizedSourceSha256": source_hash}
            )
        seen_arguments.add(argument)
        seen_imports.add(import_path)
        seen_binaries.add(binary_name)
        normalized.append(
            {
                "argument": argument,
                "importPath": import_path,
                "binaryName": binary_name,
                "expectedTestMainDeclarations": sorted(
                    normalized_test_mains, key=lambda declaration: declaration["file"]
                ),
            }
        )
    result = dict(value)
    result["target"] = target.name
    result["defaultWeightSeconds"] = float(default_weight)
    result["heavyPackages"] = normalized
    return result


class Weights(dict):
    """Per-root elapsed seconds, plus what is known about `t.Parallel()` roots.

    `parallel` names the roots that call `t.Parallel()`; `parallelism` is how
    many of them effectively run at once on the target's runner. A plain dict
    carries neither, which plans every root as serial.
    """

    def __init__(self, *args: Any, **kwargs: Any) -> None:
        super().__init__(*args, **kwargs)
        self.parallel: set[tuple[str, str]] = set()
        self.parallelism = 1.0


def process_seconds(serial: float, parallel: float, longest_parallel: float, parallelism: float) -> float:
    """Estimated wall time of one test process.

    `go test` runs a binary's serial roots first, one at a time, and then its
    `t.Parallel()` roots together. The parallel phase can end no sooner than
    its longest root and no sooner than its total work spread over the cores.
    """
    return serial + max(longest_parallel, parallel / parallelism)


def load_weights(path: Path) -> tuple[Weights, dict[str, Any]]:
    value = read_json(path)
    if not isinstance(value, dict) or value.get("schema") != WEIGHTS_SCHEMA:
        raise ValueError(f"{path}: unexpected historical-weight schema")
    rows = value.get("weights")
    if not isinstance(rows, list):
        raise ValueError(f"{path}: weights must be a list")
    parallelism = value.get("parallelism", 1.0)
    if (
        not isinstance(parallelism, (int, float))
        or isinstance(parallelism, bool)
        or not math.isfinite(float(parallelism))
        or not 1.0 <= float(parallelism) <= 1024.0
    ):
        raise ValueError(f"{path}: parallelism must be from 1 through 1024")
    weights = Weights()
    weights.parallelism = float(parallelism)
    for position, row in enumerate(rows):
        if not isinstance(row, dict):
            raise ValueError(f"{path}: weights[{position}] is not an object")
        package, name, seconds = row.get("package"), row.get("name"), row.get("seconds")
        if not isinstance(package, str) or not package or not isinstance(name, str) or not name:
            raise ValueError(f"{path}: weights[{position}] has an invalid key")
        if (
            not isinstance(seconds, (int, float))
            or isinstance(seconds, bool)
            or not math.isfinite(float(seconds))
            or float(seconds) < 0
        ):
            raise ValueError(f"{path}: weights[{position}] seconds must be finite and non-negative")
        key = (package, name)
        if key in weights:
            raise ValueError(f"{path}: duplicate weight for {package}::{name}")
        parallel = row.get("parallel", False)
        if not isinstance(parallel, bool):
            raise ValueError(f"{path}: weights[{position}] parallel must be a boolean")
        weights[key] = float(seconds)
        if parallel:
            weights.parallel.add(key)
    metadata = {
        "path": path.name,
        "sha256": sha256_file(path),
        "sourceCommit": value.get("sourceCommit"),
        "source": value.get("source"),
        "entryCount": len(weights),
        "parallelism": weights.parallelism,
        "parallelCount": len(weights.parallel),
    }
    return weights, metadata


def _root_kind(name: str) -> str | None:
    return next((kind for kind in ROOT_KINDS if name.startswith(kind)), None)


def load_inventories(
    paths: Iterable[Path], target: targets.Target = targets.DEFAULT
) -> list[dict[str, Any]]:
    result: list[dict[str, Any]] = []
    seen_packages: set[str] = set()
    for path in paths:
        value = read_json(path)
        if not isinstance(value, dict) or value.get("schema") != INVENTORY_SCHEMA:
            raise ValueError(f"{path}: unexpected compiled-inventory schema")
        package = value.get("importPath")
        binary = value.get("binaryName")
        roots = value.get("roots")
        if not isinstance(package, str) or not package or package in seen_packages:
            raise ValueError(f"{path}: missing or duplicate importPath")
        if (
            not isinstance(binary, str)
            or Path(binary).name != binary
            or "/" in binary
            or "\\" in binary
            or not binary.endswith(target.binary_suffix)
        ):
            raise ValueError(f"{path}: unsafe binaryName")
        if value.get("listExitCode") != 0:
            raise ValueError(f"{path}: compiled binary listing did not exit zero")
        if not isinstance(value.get("repositorySha"), str) or not _SHA.fullmatch(value["repositorySha"]):
            raise ValueError(f"{path}: invalid repositorySha")
        if not isinstance(value.get("goVersion"), str) or not value["goVersion"].startswith("go version go"):
            raise ValueError(f"{path}: invalid goVersion")
        if not isinstance(value.get("binarySha256"), str) or not _SHA256.fullmatch(value["binarySha256"]):
            raise ValueError(f"{path}: invalid binarySha256")
        if not isinstance(value.get("binarySizeBytes"), int) or value["binarySizeBytes"] <= 0:
            raise ValueError(f"{path}: invalid binarySizeBytes")
        target_environment = {
            "GOOS": value.get("goos"),
            "GOARCH": value.get("goarch"),
            "CGO_ENABLED": value.get("cgoEnabled"),
        }
        if target_environment != target.environment:
            raise ValueError(
                f"{path}: compiled inventory target is {target_environment!r}, want {target.environment!r}"
            )
        listing_contract = value.get("listingContract")
        if listing_contract != {
            "arguments": ["-test.paniconexit0", "-test.list=."],
            "paniconexit0": True,
            "pwdMatchesPackageDirectory": True,
            "goToolDirectoryPrependedToPath": True,
        }:
            raise ValueError(f"{path}: direct binary listing contract is missing or unexpected")
        relative = _safe_relative_directory(
            value.get("packageDirectoryRelative"), f"{path}: packageDirectoryRelative"
        )
        if not isinstance(roots, list) or not roots:
            raise ValueError(f"{path}: roots must be a non-empty list")
        names: set[str] = set()
        normalized_roots: list[dict[str, str]] = []
        for position, root in enumerate(roots):
            if not isinstance(root, dict):
                raise ValueError(f"{path}: roots[{position}] is not an object")
            name, kind = root.get("name"), root.get("kind")
            if (
                not isinstance(name, str)
                or not name
                or any(character.isspace() for character in name)
                or kind not in ROOT_KINDS
                or _root_kind(name) != kind
                or name in names
            ):
                raise ValueError(f"{path}: malformed or duplicate runnable root at index {position}")
            names.add(name)
            normalized_roots.append({"name": name, "kind": kind})
        benchmarks = value.get("excludedBenchmarks")
        if (
            not isinstance(benchmarks, list)
            or any(not isinstance(name, str) or not name.startswith("Benchmark") for name in benchmarks)
            or len(benchmarks) != len(set(benchmarks))
        ):
            raise ValueError(f"{path}: excludedBenchmarks must contain unique Benchmark names")
        test_main_declarations = value.get("testMainDeclarations")
        if not isinstance(test_main_declarations, list):
            raise ValueError(f"{path}: testMainDeclarations must be a list")
        normalized_test_mains: list[dict[str, str]] = []
        seen_test_main_files: set[str] = set()
        for position, declaration in enumerate(test_main_declarations):
            if not isinstance(declaration, dict):
                raise ValueError(f"{path}: testMainDeclarations[{position}] is not an object")
            file_name = declaration.get("file")
            source_hash = declaration.get("normalizedSourceSha256")
            if (
                not isinstance(file_name, str)
                or not file_name
                or Path(file_name).name != file_name
                or "/" in file_name
                or "\\" in file_name
                or file_name in seen_test_main_files
            ):
                raise ValueError(f"{path}: invalid or duplicate TestMain file {file_name!r}")
            if not isinstance(source_hash, str) or not _SHA256.fullmatch(source_hash):
                raise ValueError(f"{path}: invalid TestMain normalized source hash for {file_name!r}")
            seen_test_main_files.add(file_name)
            normalized_test_mains.append(
                {"file": file_name, "normalizedSourceSha256": source_hash}
            )
        seen_packages.add(package)
        result.append(
            {
                "importPath": package,
                "packageArgument": value.get("packageArgument"),
                "packageDirectoryRelative": relative,
                "binaryName": binary,
                "binarySha256": value["binarySha256"],
                "binarySizeBytes": value["binarySizeBytes"],
                "repositorySha": value["repositorySha"],
                "goVersion": value["goVersion"],
                "targetEnvironment": {
                    key: target.environment[key] for key in ("GOOS", "GOARCH", "CGO_ENABLED")
                },
                "listingContract": dict(listing_contract),
                "roots": sorted(normalized_roots, key=lambda item: item["name"]),
                "excludedBenchmarks": sorted(benchmarks),
                "testMainDeclarations": sorted(
                    normalized_test_mains, key=lambda declaration: declaration["file"]
                ),
            }
        )
    return sorted(result, key=lambda item: item["importPath"])


class _Trie:
    __slots__ = ("children", "terminal")

    def __init__(self) -> None:
        self.children: dict[str, _Trie] = {}
        self.terminal = False


def _render_trie(node: _Trie) -> str:
    alternatives = [
        re.escape(character) + _render_trie(child)
        for character, child in sorted(node.children.items())
    ]
    if not alternatives:
        return ""
    body = alternatives[0] if len(alternatives) == 1 else "(" + "|".join(alternatives) + ")"
    return "(" + body + ")?" if node.terminal else body


def compressed_run_regex(names: Iterable[str]) -> str:
    ordered = sorted(set(names))
    if not ordered:
        raise ValueError("cannot create a run regex for no roots")
    root = _Trie()
    for name in ordered:
        node = root
        for character in name:
            node = node.children.setdefault(character, _Trie())
        node.terminal = True
    return "^" + _render_trie(root) + "$"


def _inventory_digest(inventories: list[dict[str, Any]]) -> str:
    encoded = json.dumps(
        inventories, sort_keys=True, ensure_ascii=False, separators=(",", ":")
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def create_plan(
    inventories: list[dict[str, Any]],
    settings: dict[str, Any],
    weights: dict[tuple[str, str], float],
    weight_metadata: dict[str, Any],
) -> dict[str, Any]:
    if not inventories:
        raise ValueError("at least one compiled inventory is required")
    target = settings_target(settings)
    if any(item.get("targetEnvironment") != target.environment for item in inventories):
        raise ValueError(f"compiled inventories are not all {target.description}")
    expected_config = {
        (item["importPath"], item["binaryName"])
        for item in settings["heavyPackages"]
    }
    actual_config = {(item["importPath"], item["binaryName"]) for item in inventories}
    if actual_config != expected_config:
        raise ValueError("compiled inventories do not exactly match configured heavy packages")
    expected_test_mains = {
        item["importPath"]: item["expectedTestMainDeclarations"]
        for item in settings["heavyPackages"]
    }
    for inventory in inventories:
        if inventory["testMainDeclarations"] != expected_test_mains[inventory["importPath"]]:
            raise ValueError(
                f"compiled TestMain declarations drifted for {inventory['importPath']}"
            )
    repository_shas = {item["repositorySha"] for item in inventories}
    go_versions = {item["goVersion"] for item in inventories}
    if len(repository_shas) != 1 or len(go_versions) != 1:
        raise ValueError("compiled inventories disagree on repository or Go version")

    parallel_roots = getattr(weights, "parallel", frozenset())
    parallelism = float(getattr(weights, "parallelism", 1.0))
    work: list[dict[str, Any]] = []
    used_weight_keys: set[tuple[str, str]] = set()
    for inventory in inventories:
        for root in inventory["roots"]:
            key = (inventory["importPath"], root["name"])
            if key in weights:
                weight = weights[key]
                source = target.weight_source
                used_weight_keys.add(key)
            else:
                weight = settings["defaultWeightSeconds"]
                source = "default-current-inventory"
            work.append(
                {
                    "importPath": inventory["importPath"],
                    "packageDirectoryRelative": inventory["packageDirectoryRelative"],
                    "binaryName": inventory["binaryName"],
                    "binarySha256": inventory["binarySha256"],
                    "name": root["name"],
                    "kind": root["kind"],
                    "weightSeconds": round(float(weight), 6),
                    "weightSource": source,
                    # A root with no history is planned as serial.
                    "parallel": key in weights and key in parallel_roots,
                }
            )

    shard_count = settings["shardCount"]
    if len(work) < shard_count:
        raise ValueError(f"{len(work)} runnable roots cannot populate {shard_count} non-empty shards")
    work.sort(key=lambda item: (-item["weightSeconds"], item["importPath"], item["name"]))
    bins: list[list[dict[str, Any]]] = [[] for _ in range(shard_count)]
    totals = [0.0] * shard_count
    # A shard runs one process per package, one after another, so its estimated
    # wall time is the sum of its processes'. Each root, slowest first, goes to
    # the shard that would finish soonest with it. With no parallel roots this
    # is longest-processing-time-first; a parallel root is free wherever it
    # hides beneath a longer one or beneath the cores' share of the work.
    processes: list[dict[str, list[float]]] = [{} for _ in range(shard_count)]

    def placed(index: int, item: dict[str, Any]) -> tuple[float, list[float]]:
        serial, parallel, longest = processes[index].get(item["importPath"], [0.0, 0.0, 0.0])
        before = process_seconds(serial, parallel, longest, parallelism)
        if item["parallel"]:
            parallel += item["weightSeconds"]
            longest = max(longest, item["weightSeconds"])
        else:
            serial += item["weightSeconds"]
        after = process_seconds(serial, parallel, longest, parallelism)
        return totals[index] - before + after, [serial, parallel, longest]

    for item in work:
        destination = min(
            range(shard_count),
            key=lambda index: (placed(index, item)[0], len(bins[index]), index),
        )
        totals[destination], processes[destination][item["importPath"]] = placed(destination, item)
        bins[destination].append(item)

    shards: list[dict[str, Any]] = []
    for index, roots in enumerate(bins):
        by_package: dict[str, list[dict[str, Any]]] = defaultdict(list)
        for root in roots:
            by_package[root["importPath"]].append(root)
        assignments: list[dict[str, Any]] = []
        for package in sorted(by_package):
            package_roots = sorted(by_package[package], key=lambda item: item["name"])
            assignments.append(
                {
                    "importPath": package,
                    "packageDirectoryRelative": package_roots[0]["packageDirectoryRelative"],
                    "binaryName": package_roots[0]["binaryName"],
                    "binarySha256": package_roots[0]["binarySha256"],
                    "runRegex": compressed_run_regex(item["name"] for item in package_roots),
                    "roots": [
                        {
                            "name": item["name"],
                            "kind": item["kind"],
                            "weightSeconds": item["weightSeconds"],
                            "weightSource": item["weightSource"],
                            **({"parallel": True} if item["parallel"] else {}),
                        }
                        for item in package_roots
                    ],
                }
            )
        shards.append(
            {
                "index": index,
                "estimatedWeightSeconds": round(totals[index], 6),
                "rootCount": len(roots),
                "assignments": assignments,
            }
        )

    unused = sorted(f"{package}::{name}" for package, name in set(weights) - used_weight_keys)
    packages = [
        {
            "importPath": item["importPath"],
            "packageDirectoryRelative": item["packageDirectoryRelative"],
            "binaryName": item["binaryName"],
            "binarySha256": item["binarySha256"],
            "binarySizeBytes": item["binarySizeBytes"],
            "rootCount": len(item["roots"]),
            "excludedBenchmarkCount": len(item["excludedBenchmarks"]),
            "testMainDeclarations": item["testMainDeclarations"],
        }
        for item in inventories
    ]
    return {
        "schema": PLAN_SCHEMA,
        "algorithm": "deterministic-greedy-process-wall-time-v2",
        "repositorySha": next(iter(repository_shas)),
        "goVersion": next(iter(go_versions)),
        "targetEnvironment": {
            key: target.environment[key] for key in ("GOOS", "GOARCH", "CGO_ENABLED")
        },
        "inventorySetSha256": _inventory_digest(inventories),
        "shardCount": shard_count,
        "rootCount": len(work),
        "packageCount": len(inventories),
        "settings": {
            "timeout": settings["timeout"],
            "commandLineLimit": settings["commandLineLimit"],
            "shuffle": settings["shuffle"],
            "testParallel": settings["testParallel"],
            "goMaxProcs": settings["goMaxProcs"],
            "defaultWeightSeconds": settings["defaultWeightSeconds"],
        },
        "historicalWeights": {
            **weight_metadata,
            "usedCount": len(used_weight_keys),
            "defaultedCount": len(work) - len(used_weight_keys),
            "unusedKeys": unused,
        },
        "packages": packages,
        "shards": shards,
    }


def parse_args(argv: list[str]) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--settings", type=Path, required=True)
    parser.add_argument("--weights", type=Path, required=True)
    parser.add_argument("--inventory", action="append", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    return parser.parse_args(argv)


def main(argv: list[str] | None = None) -> int:
    args = parse_args(sys.argv[1:] if argv is None else argv)
    try:
        settings = load_settings(args.settings)
        weights, metadata = load_weights(args.weights)
        inventories = load_inventories(args.inventory, settings_target(settings))
        plan = create_plan(inventories, settings, weights, metadata)
        write_json(args.output, plan)
    except (ValueError, OSError) as error:
        print(f"error: {error}", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

