import sys, random, re, json, math
sys.path.insert(0, sys.argv[1])
import plan_shards, targets

def inv(pkg, names, target):
    return {
        "importPath": pkg, "packageArgument": "./" + pkg, "packageDirectoryRelative": pkg,
        "binaryName": pkg + target.binary_suffix, "binarySha256": "a" * 64, "binarySizeBytes": 1,
        "repositorySha": "b" * 40, "goVersion": "go version go1.27 x",
        "targetEnvironment": dict(target.environment),
        "listingContract": {}, "roots": sorted(({"name": n, "kind": plan_shards._root_kind(n)} for n in names), key=lambda r: r["name"]),
        "excludedBenchmarks": [], "testMainDeclarations": [],
    }

def settings(target, count):
    return {"target": target.name, "shardCount": count, "defaultWeightSeconds": 0.05, "timeout": "30m",
            "commandLineLimit": 30000, "shuffle": "off", "testParallel": None, "goMaxProcs": None,
            "heavyPackages": [{"importPath": p, "binaryName": p + target.binary_suffix, "expectedTestMainDeclarations": []} for p in ("p1", "p2", "p3")]}

rng = random.Random(7)
problems = {}
trials = 0
for trial in range(3000):
    target = rng.choice([targets.WINDOWS_AMD64, targets.DARWIN_ARM64])
    names = {}
    for p in ("p1", "p2", "p3"):
        n = rng.randint(1, 40)
        base = set()
        while len(base) < n:
            kind = rng.choice(["Test", "Example", "Fuzz"])
            s = kind + "".join(rng.choice("AB_ab1é.") for _ in range(rng.randint(0, 5)))
            if "." in s and rng.random() < 0.9:
                continue
            base.add(s)
