    want = {(p, n) for p in names for n in names[p]}
    if set(seen) != want:
        problems.setdefault("INCOMPLETE", []).append((mode, count, len(want - set(seen))))
    if len(plan["shards"]) != count:
        problems.setdefault("shard count", []).append(count)
print("valid plans checked:", trials)
for k, v in problems.items():
    print(k, "x", len(v), "e.g.", v[0])

// Checks every plan runRegex with Go's own regexp against the compiled inventories.
package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

type root struct{ Name string }
type inventory struct {
	ImportPath string
	Roots      []root
}
type assignment struct {
	ImportPath string
	RunRegex   string
	Roots      []root
}
type plan struct {
	Shards []struct {
		Index       int
		Assignments []assignment
	}
}

func main() {
	bundle := os.Args[1]
	names := map[string][]string{}
	files, _ := filepath.Glob(filepath.Join(bundle, "inventories", "*.inventory.json"))
	for _, f := range files {
		var inv inventory
		data, _ := os.ReadFile(f)
		if err := json.Unmarshal(data, &inv); err != nil {
			panic(err)
		}
		for _, r := range inv.Roots {
			names[inv.ImportPath] = append(names[inv.ImportPath], r.Name)
		}
	}
	var p plan
	data, _ := os.ReadFile(filepath.Join(bundle, "plan.json"))
	if err := json.Unmarshal(data, &p); err != nil {
		panic(err)
	}
	bad, checked, longest := 0, 0, 0
	for _, s := range p.Shards {
		for _, a := range s.Assignments {
			// testing splits -test.run on unbracketed '/', so a slash would change meaning.
			if strings.Contains(a.RunRegex, "/") {
				fmt.Println("SLASH in regex", s.Index, a.ImportPath)
				bad++
			}
			rx, err := regexp.Compile(a.RunRegex)
			if err != nil {
				fmt.Println("GO COMPILE ERROR", s.Index, a.ImportPath, err)
				bad++
				continue
			}
			if len(a.RunRegex) > longest {
				longest = len(a.RunRegex)
			}
			var got, want []string
			for _, n := range names[a.ImportPath] {
				if rx.MatchString(n) {
					got = append(got, n)
				}
			}
			for _, r := range a.Roots {
				want = append(want, r.Name)
			}
			sort.Strings(got)
			sort.Strings(want)
			checked++
			if strings.Join(got, ",") != strings.Join(want, ",") {
				fmt.Println("MISMATCH", s.Index, a.ImportPath, len(got), len(want))
				bad++
			}
		}
	}
	fmt.Println("assignments checked:", checked, "bad:", bad, "longest regex bytes:", longest)
}

