"""Doctor copies of one real green evidence set and run the verifier on each."""
import hashlib, json, os, shutil, subprocess, sys, tempfile
from pathlib import Path

HARNESS, BUNDLE, BASE = Path(sys.argv[1]), Path(sys.argv[2]), Path(sys.argv[3])
sys.path.insert(0, str(HARNESS))
import plan_shards  # noqa: E402

def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()

def load_events(path):
    return [json.loads(line) for line in Path(path).read_text().splitlines() if line.strip()]

def dump_events(path, events):
    Path(path).write_text("".join(json.dumps(e) + "\n" for e in events))

def rj(path):
    return json.loads(Path(path).read_text())

def wj(path, value):
    Path(path).write_text(json.dumps(value, indent=2) + "\n")

def make(root):
    bundle = root / "bundle"
    bundle.mkdir()
    for item in BUNDLE.iterdir():
        if item.name == "binaries":
            (bundle / "binaries").mkdir()
            for binary in item.iterdir():
                os.symlink(binary, bundle / "binaries" / binary.name)
        elif item.is_dir():
            shutil.copytree(item, bundle / item.name)
        else:
            shutil.copy(item, bundle / item.name)
    shutil.copytree(BASE / "shards", root / "shards")
    shutil.copytree(BASE / "other", root / "other")
    return bundle, root / "shards", root / "other"

def verify(root, bundle, shards, other):
    out = root / "report.json"
    r = subprocess.run([sys.executable, "-B", str(HARNESS / "verify_results.py"), "--bundle", str(bundle),
                        "--shard-results", str(shards), "--other-results", str(other), "--output", str(out),
                        "--target", "darwin/arm64"], capture_output=True, text=True)
    fails = [l for l in r.stderr.splitlines() if l.startswith("FAIL")]
    return r.returncode, fails

PLAN = rj(BUNDLE / "plan.json")
def pick(shard_index=0, package_suffix="gitutil"):
    for a in PLAN["shards"][shard_index]["assignments"]:
        if a["importPath"].endswith(package_suffix):
            return a
    return PLAN["shards"][shard_index]["assignments"][0]

def restamp_plan(bundle, shards, other):
    h = sha(bundle / "plan.json")
    for m in list(shards.rglob("shard-metadata.json")) + list(other.rglob("other-metadata.json")):
        v = rj(m); v["planSha256"] = h; wj(m, v)

SCENARIOS = {}
def scenario(f):
    SCENARIOS[f.__name__] = f
    return f

A0 = pick(0)
PKG, ROOT = A0["importPath"], A0["roots"][0]["name"]
ev0 = lambda shards, i=0: shards / f"shard-{i}" / "shard-events.jsonl"

@scenario
def s00_untouched(b, s, o): pass

@scenario
def s01_delete_one_roots_events(b, s, o):
    dump_events(ev0(s), [e for e in load_events(ev0(s)) if not (e.get("Package") == PKG and (e.get("Test") or "").split("/")[0] == ROOT)])

@scenario
def s02_flip_root_pass_to_fail_only(b, s, o):
    ev = load_events(ev0(s))
    for e in ev:
        if e.get("Package") == PKG and e.get("Test") == ROOT and e.get("Action") in ("pass", "skip"):
            e["Action"] = "fail"
    dump_events(ev0(s), ev)

@scenario
def s03_duplicate_root_in_same_shard(b, s, o):
    ev = load_events(ev0(s))
    extra = [e for e in ev if e.get("Package") == PKG and e.get("Test") == ROOT and e.get("Action") in ("run", "pass", "skip")]
    dump_events(ev0(s), ev[:-1] + extra + ev[-1:])

@scenario
def s04_root_also_ran_in_another_shard(b, s, o):
    ev = load_events(ev0(s))
    extra = [e for e in ev if e.get("Package") == PKG and e.get("Test") == ROOT and e.get("Action") in ("run", "pass", "skip")]
    other_index = next(sh["index"] for sh in PLAN["shards"][1:] if any(a["importPath"] == PKG for a in sh["assignments"]))
    ev1 = load_events(ev0(s, other_index))
    dump_events(ev0(s, other_index), ev1[:-1] + extra + ev1[-1:])

@scenario
def s05_swap_event_files_of_two_shards(b, s, o):
    a, c = ev0(s, 0).read_bytes(), ev0(s, 1).read_bytes()
    ev0(s, 0).write_bytes(c); ev0(s, 1).write_bytes(a)

@scenario
def s06_delete_one_shard_dir(b, s, o): shutil.rmtree(s / "shard-3")

@scenario
def s07_delete_one_events_file(b, s, o): ev0(s, 3).unlink()

@scenario
def s08_truncate_events_at_line_boundary(b, s, o):
    ev = load_events(ev0(s)); dump_events(ev0(s), ev[: len(ev) // 2])

@scenario
def s09_truncate_events_mid_line(b, s, o):
    data = ev0(s).read_bytes(); ev0(s).write_bytes(data[: len(data) // 2 + 7])

@scenario
def s10_empty_events_file(b, s, o): ev0(s).write_bytes(b"")

@scenario
def s11_shard_evidence_replaced_by_another_shards(b, s, o):
    shutil.rmtree(s / "shard-3"); shutil.copytree(s / "shard-4", s / "shard-3")

@scenario
def s12_invocation_recorded_binary_sha_changed(b, s, o):
    m = rj(s / "shard-0" / "shard-metadata.json"); m["invocations"][0]["binarySha256"] = "0" * 64; wj(s / "shard-0" / "shard-metadata.json", m)

@scenario
def s13_shard_repository_sha_changed(b, s, o):
    m = rj(s / "shard-0" / "shard-metadata.json"); m["repositorySha"] = "0" * 40; m["repositoryShaAfter"] = "0" * 40; wj(s / "shard-0" / "shard-metadata.json", m)

@scenario
def s14_shard_plan_sha_changed(b, s, o):
    m = rj(s / "shard-0" / "shard-metadata.json"); m["planSha256"] = "0" * 64; wj(s / "shard-0" / "shard-metadata.json", m)

@scenario
def s15_shard_target_is_windows(b, s, o):
    m = rj(s / "shard-0" / "shard-metadata.json"); m["targetEnvironment"] = {"CGO_ENABLED": "1", "GOARCH": "amd64", "GOOS": "windows"}; wj(s / "shard-0" / "shard-metadata.json", m)

@scenario
def s16_invocation_exit_code_1_only(b, s, o):
    m = rj(s / "shard-0" / "shard-metadata.json"); m["invocations"][0]["exitCode"] = 1; wj(s / "shard-0" / "shard-metadata.json", m)

@scenario
def s17_crash_mid_run_no_package_terminal(b, s, o):
    ev = load_events(ev0(s))
    last = max(i for i, e in enumerate(ev) if e.get("Package") == PKG)
    del ev[last]
    dump_events(ev0(s), ev)

@scenario
def s18_subtest_fail_event_only(b, s, o):
    ev = load_events(ev0(s)); ev.insert(len(ev) - 1, {"Action": "fail", "Package": PKG, "Test": ROOT + "/injected"}); dump_events(ev0(s), ev)

@scenario
def s19_root_pass_replaced_by_skip(b, s, o):
    ev = load_events(ev0(s))
    for e in ev:
        if e.get("Package") == PKG and e.get("Test") == ROOT and e.get("Action") == "pass":
            e["Action"] = "skip"
    dump_events(ev0(s), ev)

@scenario
def s20_bundle_binary_modified(b, s, o):
    target = next((b / "binaries").iterdir()); data = target.read_bytes(); target.unlink(); target.write_bytes(data[:-1] + bytes([data[-1] ^ 1]))

@scenario
def s21_other_delete_one_package_events(b, s, o):
    p = o / "other-events.jsonl"; ev = load_events(p); victim = rj(o / "other-metadata.json")["expectedPackages"][0]
    dump_events(p, [e for e in ev if e.get("Package") != victim])

@scenario
def s22_other_flip_package_pass_to_fail(b, s, o):
    p = o / "other-events.jsonl"; ev = load_events(p)
    e = next(e for e in ev if e.get("Action") == "pass" and "Test" not in e); e["Action"] = "fail"; dump_events(p, ev)

@scenario
def s23_other_test_fail_event_only(b, s, o):
    p = o / "other-events.jsonl"; ev = load_events(p)
    e = next(e for e in ev if e.get("Action") == "pass" and e.get("Test")); e["Action"] = "fail"; dump_events(p, ev)

@scenario
def s24_other_expected_packages_shortened_with_events(b, s, o):
    m = rj(o / "other-metadata.json"); victim = m["expectedPackages"].pop(0); wj(o / "other-metadata.json", m)
    p = o / "other-events.jsonl"; dump_events(p, [e for e in load_events(p) if e.get("Package") != victim])

@scenario
def s25_other_test_exit_code_1_only(b, s, o):
    m = rj(o / "other-metadata.json"); m["testExitCode"] = 1; wj(o / "other-metadata.json", m)

@scenario
def s26_plan_drops_root_consistently_restamped(b, s, o):
    """A planner bug that silently omits a root, with every downstream artifact self-consistent."""
    plan = rj(b / "plan.json")
    a = next(x for x in plan["shards"][0]["assignments"] if x["importPath"] == PKG)
    a["roots"] = [r for r in a["roots"] if r["name"] != ROOT]
    a["runRegex"] = plan_shards.compressed_run_regex(r["name"] for r in a["roots"])
    plan["shards"][0]["rootCount"] -= 1
    plan["rootCount"] -= 1
    wj(b / "plan.json", plan)
    m = rj(s / "shard-0" / "shard-metadata.json")
    for inv in m["invocations"]:
        if inv["package"] == PKG:
            inv["rootCount"] -= 1
    wj(s / "shard-0" / "shard-metadata.json", m)
    restamp_plan(b, s, o)
    s01_delete_one_roots_events(b, s, o)

@scenario
def s27_plan_root_in_two_shards_consistently(b, s, o):
    plan = rj(b / "plan.json")
    other_index = next(sh["index"] for sh in plan["shards"][1:] if any(x["importPath"] == PKG for x in sh["assignments"]))
    a = next(x for x in plan["shards"][other_index]["assignments"] if x["importPath"] == PKG)
    a["roots"] = sorted(a["roots"] + [dict(A0["roots"][0])], key=lambda r: r["name"])
    a["runRegex"] = plan_shards.compressed_run_regex(r["name"] for r in a["roots"])
    plan["shards"][other_index]["rootCount"] += 1
    wj(b / "plan.json", plan)
    restamp_plan(b, s, o)
    s04_root_also_ran_in_another_shard(b, s, o)
    m = rj(s / f"shard-{other_index}" / "shard-metadata.json")
    for inv in m["invocations"]:
        if inv["package"] == PKG:
            inv["rootCount"] += 1
    wj(s / f"shard-{other_index}" / "shard-metadata.json", m)

@scenario
def s28_inventory_and_plan_both_drop_root(b, s, o):
    """Prepare-side loss: the root vanishes from the inventory the verifier treats as truth."""
    for path in (b / "inventories").glob("*.inventory.json"):
        inv = rj(path)
        if inv["importPath"] == PKG:
            inv["roots"] = [r for r in inv["roots"] if r["name"] != ROOT]
            wj(path, inv)
    invs = plan_shards.load_inventories(sorted((b / "inventories").glob("*.inventory.json")), plan_shards.targets.DARWIN_ARM64)
    plan = rj(b / "plan.json")
    plan["inventorySetSha256"] = plan_shards._inventory_digest(invs)
